# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def make_student(student_id: str, last_name: str, first_name: str) -> Student:
    return Student(student_id, last_name, first_name, "A")


class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("1005", "Varrow", "Ines"),
            make_student("1002", "Halloway", "Juno"),
            make_student("1004", "Thistle", "Bram"),
            make_student("1001", "Dunmere", "Piet"),
            make_student("1003", "Quillon", "Sefa"),
        ]

    def test_orders_by_last_name_and_fills_rows(self):
        self.assertEqual(
            seat_rows(self.students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quillon, Sefa | Thistle, Bram",
                "Row 3: Varrow, Ines",
            ],
        )

    def test_one_row_when_seats_cover_everyone(self):
        rows = seat_rows(self.students, 30)
        self.assertEqual(len(rows), 1)
        self.assertTrue(rows[0].startswith("Row 1: Dunmere, Piet"))

    def test_same_last_name_is_ordered_by_first_name(self):
        pair = [
            make_student("2", "Lark", "Zed"),
            make_student("1", "Lark", "Amos"),
        ]
        self.assertEqual(seat_rows(pair, 2), ["Row 1: Lark, Amos | Lark, Zed"])

    def test_input_list_is_not_reordered(self):
        before = [student.student_id for student in self.students]
        seat_rows(self.students, 2)
        self.assertEqual([student.student_id for student in self.students], before)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
